statements.statement:
SELECT hex(TPoll.PollK) AS PollK, TPoll.FName, TPoll.FDescription, DATE(TPoll.CreateD) AS CreateD,
   (SELECT COUNT(DISTINCT TPollVote.FTie) FROM TPollVote JOIN TPollAnswer ON TPollAnswer.PollAnswerK = TPollVote.PollAnswerK 
   JOIN TPollQuestion ON TPollQuestion.PollQuestionK = TPollAnswer.PollQuestionK 
   WHERE TPollQuestion.PollK = TPoll.PollK) 
   AS TotalVotes FROM TPoll
{++where} 
{++orderby} 
{++limit}
